INSERT INTO `majors` (`id`, `name`, `description`, `part_time`, `full_time`) VALUES
('SG111', 'Bachelor of Computer Science (Cyber Security)', 'This programme provides understanding in the structure of data and the role it plays in delivering solutions to complex problems. In this major, you will learn to use current and emerging technologies related to cyber security, such as blockchain, cryptocurrency, multimedia security, Internet of Things (IoT) security and obfuscation.', 0, 1),
('SG766', 'Bachelor of Computer Science (Big Data)', 'This programme provides understanding in the structure of data and the role it plays in delivering solutions to complex problems in science, society and business. You will study subjects in data mining, big data management, database performance tuning, distributed systems and cloud computing.', 1, 1),
('SG122', 'Bachelor of Computer Science (Digital Systems Security)', 'This programme develops knowledge, strategic thinking, research and communication skills needed to succeed in this rapidly growing industry. You will learn advanced security programming and techniques, and understand strategies in information protection and coding, to ensure correctness, security and data authenticity.', 1, 1),
('SG133', 'Bachelor of Computer Science (Game and Mobile Development)', 'This programme provides understanding in the structure of data and the role it plays in delivering solutions to complex problems. This major will equip you with skills to apply techniques to the development of video games and related systems on computers and mobile platforms, including devices such as mobile phones, tablets and wearable devices.', 0, 1),
('SG868', 'Bachelor of Information Technology', 'A UOW Information Technology degree will provide you with the skills to make a company more productive and efficient through the use of IT. The degree has a solid foundation in theory, analysis, design, and implementation. These core skills are extended into a range of key areas, including systems administration, data and process management, web development and aspects of software engineering.', 1, 0),
('SG144', 'Bachelor of Business Information Systems', 'The degree programme provides the knowledge and skills to design, develop and integrate information systems to support business needs, giving an organisation the competitive edge in the global marketplace. The BBIS spans the information systems lifecycle: from requirements gathering, through design, coding, implementation and testing, to management of ongoing evolving systems, all from a business perspective.', 0, 1);
INSERT INTO `projects` (`id`, `proj_id`, `name`, `description`, `available_for`, `active`) VALUES
(1, 'CSIT-21-S1-01', 'SIM Open House', 'Open House is an opportunity for SIM to create a marketing campaign and collect data to present to future students. This project aims to develop a professional mobile application to bring your marketing strategy to the next level.\r\n\r\nStudents are required to do a proper requirements analysis by collecting requirements from both students and SIM marketing department. Based on the requirements, a mobile application is to be developed. Evaluation by students and SIM marketing department should also be part of the project.\r\n\r\nA sample application that might be helpful is called uni-verse that is used in UNSW Open Day. However, students must verify and customise the requirements and features with SIM stakeholders.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(2, 'CSIT-21-S1-02', 'Typing Habit Gesture Authentication System', 'Passwords have been the main protection system that people use to enter and use digital resources. The main idea of this project is to replace a password system with a typing gesture habit authentication system. When the system is on, the user will be asked to type a sentence that is given on the screen, and the software will determine the user based on the typing behaviour pattern.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(3, 'CSIT-21-S1-03', 'GroupBuy', 'A group buy site sells a service or item after a certain number of agreements to buy the item has reached. The business model is based on the U.S. business Groupon.\r\n\r\nThis project aims at developing a mobile ecommerce application based on the concept of group buy. Each item listed in this platform has a discounted price and an associated minimum number to be reached. The shoppers can browse (and search) the items for sale in this platform. Once a shopper has the interest to buy an item, he can either add it to the watch list, or join an existing group to buy this item. The shopper can also start a new group for the item. Once a new group is created, all users who have the same item in their watch list will be notified and be invited to join the group to buy. Once the minimum group size is reached, transaction will be completed for all members in that group at the discounted price. A shopper has the option to leave group before the minimum number is reached. A group might also be dismissed after a timer expires.\r\n\r\nUser account management is a standard function of this application.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(4, 'CSIT-21-S1-04', 'My News Headlines', 'This project is to develop a mobile application to assist a user in browsing vast amount of information on the Internet.\r\n\r\nThe application starts with a small user profile which indicates the areas/topics that the user is interested in. The crawling component of the application will use this profile to visit a number of public websites (for example, news websites) to download contents or create indices of other sites’ contents. When the selected contents are presented to the user, his reading history will be tracked to further improve the profile for more accurate crawling in the future. The contents or indices will be updated periodically or when the user restarts the application. The user can also update the contents by sliding the screen or pressing a button.\r\n\r\nThe application can also send some relevant ads to the user based on his profile and reading history.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(5, 'CSIT-21-S1-05', 'Multiplayer Battle Arena for Mobile Devices', 'The goal of this project is to develop a multiplayer battle arena game for mobile devices. Players will form two teams with each player controlling a single character. Players should be able to choose from a number of characters, each with different characteristics. The two teams will fight to achieve the map objectives (e.g., destroy opposing team’s base, occupy and defend territories for points, kill enemy forces). The map should also spawn AI NPCs to aid each team, AI NPCs should also take control if players disconnect from the game.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(6, 'CSIT-21-S1-06', 'First Person Puzzle Game', 'This project involves developing a puzzle game from a first person perspective. The game should involve puzzle challenges that the player has to solve by interacting with the environment and objects in the environment in a specific way. Clues can be given to aid the player in solving the puzzles. More advanced challenges may include features like completing the challenges within a certain time frame, etc.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(7, 'CSIT-21-S1-07', 'Financial Market Simulator', 'Financial markets are volatile and depend on many different factors. For example, a big world event can cause the financial market to crash, or a trade deal between two countries might stir investor confidence. The purpose of this project is to analyse financial markets data patterns in order to predict how the market will react to world events.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(8, 'CSIT-21-S1-08', 'Side Channel Analyser and Eliminator', 'Side channel attacks, such as time based attacks, are critical issues in the implementation of cryptographic algorithms. This project should allow the side channel information of some types, probably timing and perhaps other sources such as sound and power usage, to be measured. These measurements would provide a statistical baseline and if there is significant variance detected as a function of key size or key value that may correlated, the application could recommend action be taken.\r\n\r\nThe application could then build a wrapper around the appropriate modules to eliminate the leaked information. Such wrappers could include the use of delays to smooth out the measured provide and make the timing independent of, for example, the specific keys being used.\r\n\r\nThe group should probably initially limit attention to side channels in communication, specifically timing. It would be necessary to be able to modify the code of the analysed program and automating this probably wouldn’t be easy.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(9, 'CSIT-21-S1-09', 'Containerisation Technology for Big Data Education', 'Big data requires “big machines” which may not be very accessible resources in university education. Usually, big data environments (such as Apache Hadoop) are deployed in stand-alone machines (e.g., desktops or VMs) in the university computer labs (which are shared by multiple subjects). This project aims to use the containerisation technology to enable the fast deployment of a Hadoop cluster in the university lab environment.\r\n\r\nExpected outcome: Docker images with Hadoop and other components (e.g., Hive, HBase and Spark); a deployment documentation', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(10, 'CSIT-21-S1-10', 'Event Stream Virtualisation and Analytics', 'Event streams are ubiquitous. Various forms of event streams include business transactions, clickstreams and call paths. The value of those streams depends on the capability of moving and analysing the data. Nowadays more and more companies deploy streaming platforms to route the data between different components in the IT infrastructure. This project aims to implement functions that virtualise and analyse event streams in one of the leading streaming platforms such as Apache Kafka. One essential requirement is efficiency as the results should be generated with minimum delay.\r\n\r\nExpected outcome: source code of the project and case studies', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(11, 'CSIT-21-S1-11', 'Sentient Analysis in Spark Streaming', 'In the today’s world of opinions, Twitter is a popular social media which people often take to express their opinions. Due to the unregulated characteristic of “twitts”, it is challenging to analyse the sentiments on topics that are worthy of attentions (e.g., social matters and political debates). This project aims to develop a software tool to analyse the sentiments of Twitter data in Spark Streaming (i.e., Spark’s streaming component) based on the start-of-the-art deep learning models (e.g., RNN).\r\n\r\nExpected outcome: A Spark project', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(12, 'CSIT-21-S1-12', 'Management of Machine Learning (ML) Workflows', 'Real-world ML pipelines usually include a number of stages. A workflow system can facilitate the design, management and monitoring of ML pipelines. This project implements a workflow system for one widely used ML library, such as TensorFlow. The workflow system should provide interfaces to compose ML models with control steps (e.g., fork and join). It should include a function to monitor the execution status of the pipeline.\r\n\r\nExpected outcome: Source code of the workflow system; case studies', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(13, 'CSIT-21-S1-13', 'Efficient hybrid encryption for multimedia delivery', 'The idea of the project is to provide a secure broadcast server, such as Netflix, which delivers multimedia content. Ideally, it should be encrypted using a hybrid encryption, while making use of broadcasting technology. Anyone who subscribes to the system can view the contents whilst the rest cannot view it. The demonstration produced should include PCs, tablets and mobile devices to view the contents and the users can be added/revoked dynamically.\r\n\r\nExpected outcome: Source code of the workflow system; case studies', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(14, 'CSIT-21-S1-14', 'Efficient SSH tunneling', 'As we know, SSH client can provide tunnelling via different mechanisms. The idea of the project is to create a new SSH client which can efficiently do tunnelling and easily configure with the system.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(15, 'CSIT-21-S1-15', 'Secure workgroup collaboration', 'This project is to create a secure workgroup environment where users can exchange messages, store files (eg. Word or PPT files) to be shared with other online users, securely.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(16, 'CSIT-21-S1-16', 'Obfuscator for Java programming', 'The idea of this project is to construct an obfuscator for Java programming. The program will still be compilable under Java. The program should compare the efficiency of the result compared to the original source code.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(17, 'CSIT-21-S1-17', 'Obfuscator for Python programming', 'The idea of this project is to construct an obfuscator for python programming. The program will still be executable under Python. The program should compare the efficiency of the result compared to the original source code.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(18, 'CSIT-21-S1-18', 'Obfuscator for C++ programming', 'The idea of this project is to construct an obfuscator for C++ programming. The program will still be compliable under C++. The program should compare the efficiency of the result compared to the original source code.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(19, 'CSIT-21-S1-19', 'FYP Management Tool', 'This project is to design and develop a tool to facilitate the management of the final year projects at SIM. With this tool, students can easily navigate the project list and select the projects they would like to do. At the same time, the subject coordinator can optimise the project allocation.\r\n\r\nSome initial functional requirements are as follows:\r\n1. The tool should be able to import student information (such as their program and major) from an external file.\r\n2. The tool should allow the subject coordinator to both add new projects rectly and import the project information from an external file. Each project should have a title, a description, and optionally required knowledge.\r\n3. The tool should allow students to search for, to view, and to select up to three projects, and record their selection.\r\n4. The tool should allow the subject coordinator to specify additional criteria, such as “each group should have at least one student from Bachelor of Computer Science”, for project allocation.\r\n5. The tool should allow the subject coordinator to specify optimisation objectives such as “students doing major XXX should have the priority to do the project related to XXX”.\r\n6. The tool should allow the subject coordinator to allocate the projects based on the students’ preference, additional criteria, and optimisation objectives.\r\n\r\nThe project team is encouraged to interview key stakeholders such as the students, the subject coordinator, the supervisors, the APDs to further develop the detailed requirements.', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(20, 'CSIT-21-S1-20', 'Discovering Periodic Patterns in Audit Data', 'The audit subsystems of many commercial database management systems allow for very detailed specification of what operations on data, which database objects, and which database users should be observed and what information should be recorded in the audit trails. Audit activities target the database operations performed by the particular users as well as the operations performed on the particular database objects in the given periods of time. Audit data usually used for the data security purposes can also be used for prediction of the future database workloads. Information about periodic repeatability of data processing tasks can be used to predict the future database workloads. An objective of this project is to implement a software tool for analysis of large data sets obtained from recording audit data over the long periods of time to discover periodically processed identical operations on data. The project can use any database system that provides auditing features. It is expected that the outcomes of audit analysis, i.e. periodic patterns of processing the same operations and/or group of operations will be visualized by the project.\r\n\r\nSoftware required - Any database system with auditing features, Java, JDBC', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1),
(21, 'CSIT-21-S1-21', 'Command Line Interface (CLI) and Graphical User Interface (GUI) ', 'HBase big data store lacks a powerful Command line Interface (CLI) and Graphical User Interface (GUI) that can be used for formulation and processing of ad-hoc data manipulation, retrieval, and management tasks on the contents of Big Tables. An objective of the project is to design and implement both CLI and GUI to HBase. Both interfaces should provide the user with Google\'s BigTable view of data stored in HBase systems. It is required that CLI would be much more powerful and flexible than the already existing CLIs.\r\n\r\nSoftware required - Hadoop, Apache Hbase, Java', '[\"SG111\", \"SG766\", \"SG122\", \"SG133\", \"SG868\", \"SG144\"]', 1);
